PYTHONPATH=/workspace/.tools/pylib python3 - <<'PY'
import pycdlib
iso=pycdlib.PyCdlib(); iso.open('/workspace/alpine.iso')
def walk(p, depth=0):
    for c in iso.list_children(iso_path=p):
        n=c.file_identifier().decode(errors='replace')
        if n in ('.','..'): continue
        child=(p.rstrip('/')+'/'+n)
        if c.is_dir():
            print('  '*depth+child+'/')
            if depth<2: walk(child, depth+1)
        else:
            print('  '*depth+child, c.get_data_length())
walk('/')
PY

mkdir -p /tmp/initrd
gzip -dc /workspace/.boot/initramfs-lts > /tmp/initramfs.cpio
python3 - <<'PY'
import os,stat
data=open('/tmp/initramfs.cpio','rb').read(); i=0
while True:
    if data[i:i+6] not in (b'070701',b'070702'): break
    def h(o,l): return int(data[i+o:i+o+l],16)
    mode=h(14,8); fs=h(54,8); ns=h(94,8); name=data[i+110:i+110+ns-1].decode(errors='replace')
    i+=110+ns; i=(i+3)&~3; c=data[i:i+fs]; i+=fs; i=(i+3)&~3
    if name=='TRAILER!!!': break
    p=os.path.join('/tmp/initrd',name.lstrip('/')); t=stat.S_IFMT(mode)
    if t==stat.S_IFDIR: os.makedirs(p,exist_ok=True)
    elif t==stat.S_IFLNK:
        os.makedirs(os.path.dirname(p),exist_ok=True)
        if not os.path.lexists(p): os.symlink(c.decode(),p)
    else:
        os.makedirs(os.path.dirname(p),exist_ok=True); open(p,'wb').write(c)
PY
